#include "nsISupports.idl"

interface IOAuth2CustomDetails;

/**
 * Interface for constructing XPCOM object parameterized on a value.
 */
[scriptable, uuid(b783f2c3-f836-4695-a320-1fd8378d57e9)]
interface IExchangeLanguageInteropFactory : nsISupports {

  /**
   * Return OAuth2 custom details for the given server type, host, and user.
   */
  IOAuth2CustomDetails createOAuth2Details(
    in AUTF8String type,
    in AUTF8String hostname,
    in AUTF8String username);

};
